# ---- helper: guard an inner catch whose log object carries `error: V instanceof Error ? V.message : String(V),`
import re as _re
def gc(var):
    text=mk.rd(CF)
    cl=_re.search(r'^( *)\} catch \(%s: \w+\) \{\n'%var,text,_re.M)
    assert cl,var
    ec='error: %s instanceof Error ? %s.message : String(%s),'%(var,var,var)
    ei=text.index(ec,cl.end()); assert ei-cl.end()<900,(var,ei-cl.end())
    end=text.index('\n',ei)+1
    old=text[cl.start():end]
    assert text.count(old)==1,var
    body=old[len(cl.group(0)):]
    m=_re.match(r' *',body); ind=len(m.group(0))
    new=cl.group(0)+G(ind,coer(var))+body.replace(ec,'error: reason,')
    return (old,new)

