# ================= B: coercing form for the six PR 1925 guards + retentionScheduler (G105-F1 shape)
VF=OS+'src/routes/verification.ts'
V2F=OS+'src/routes/verificationV2.ts'
RSF=OS+'src/services/retentionScheduler.ts'
REFVER=TD+'ks1868-verification-verify-hash-status-route-catches-p1-unreadable-throw.test.ts'
def hg(path,var,ctx,call='logger.error'):
    text=mk.rd(path)
    key="%s('%s'"%(call,ctx)
    assert text.count(key)==1,(ctx,text.count(key))
    i=text.index(key)
    rexpr="reason = %s instanceof Error ? %s.message : String(%s);"%(var,var,var)
    rl=text.rindex(rexpr,0,i); assert i-rl<260,(ctx,i-rl)
    ls=text.rindex('\n',0,rl)+1; le=text.index('\n',i)+1
    old=text[ls:le]; assert text.count(old)==1
    return (old,old.replace(rexpr,"reason = String(%s instanceof Error ? %s.message : %s);"%(var,var,var)))
B_REUSE="This is the coercing form that PR 1924 merged in routes/certifications.ts (`reason = String(error instanceof Error ? error.message : error);`, for example at line 1521 there, with the reason at line 1094, KS-1844 gate 36 F1): the SAME expression the guard already carries, wrapped in `String(...)`; the local `try`, the fallback constant and the log line are unchanged. No helper added."
B_COMMON_WRONG=" The guard (KS-1868 O66/O70, merged in PR 1925) reads `reason = X instanceof Error ? X.message : String(X);` inside a local `try` and falls back to the constant `'unreadable thrown value'` when that throws. It does NOT coerce `message`: for an Error whose `message` getter RETURNS a hostile non-string (a revoked Proxy, or an object whose `toJSON` throws) `reason` is that object, the guard's try does not throw, and the REAL winston logger (KS-1348 redaction and format) throws on it inside `logger.error`, outside the try: the request gets NO ANSWER (QA gate 105 G105-F1, measured at base and head; PR 1925's own cells use a jest.fn logger, which never formats its arguments and so cannot reproduce it). The fix is one token per site: `reason = String(X instanceof Error ? X.message : X);`, which turns an object into its string form and sends a value String() cannot read to the existing fallback."
B_DISC="Persisted state: none either way (these catches log and answer a constant). Disclosure: the response body is the same constant for an ordinary Error and for every hostile value; the thrown text never reaches the response; a hostile message is logged as `unreadable thrown value` (a value String() cannot read) or as its string form (`[object Object]`)."

